css:
* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.folder-widget {
  --title-color: #0E5B67;
  --subtitle-color: #728DA5;
  --text-color: #246975;
  --border-color: #4B83A7;
  --separator-color: #C8DAE5;
  --mechanical-color: #4E4E4E;
  --mechanical-fill: #D7D8DB;

  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  color: var(--text-color);
  font-family: Arial, Helvetica, sans-serif;
  pointer-events: none;
  user-select: none;
  opacity: var(--w-opacity, 1);
}

.folder-stage {
  position: absolute;
  top: 0;
  left: 0;
  width: 1610px;
  height: 755px;
  background: transparent;
  transform-origin: top left;
}

.screen-header {
  position: absolute;
  top: 14px;
  left: 30px;
  right: 30px;
  height: 56px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}

.screen-heading {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
}

.screen-title {
  color: var(--title-color);
  font-size: 28px;
  font-weight: 700;
  line-height: 1.05;
  white-space: nowrap;
}

.screen-subtitle {
  color: var(--subtitle-color);
  font-size: 14px;
  line-height: 1.3;
  white-space: nowrap;
}

.screen-subtitle[hidden] {
  display: none;
}

.screen-reference {
  margin-top: 3px;
  padding: 6px 12px;
  border: 1px solid var(--separator-color);
  border-radius: 4px;
  background: transparent;
  color: #526D80;
  font-size: 13px;
  font-weight: 700;
  line-height: 18px;
  white-space: nowrap;
}

.process-diagram {
  position: absolute;
  top: 88px;
  left: 30px;
  width: 1550px;
  height: 570px;
  overflow: hidden;
  font-family: Arial, Helvetica, sans-serif;
}

.equipment-title {
  fill: var(--title-color);
  font-size: 20px;
  font-weight: 700;
  text-anchor: middle;
}

.device-tag {
  fill: #405B6B;
  font-size: 13px;
  font-weight: 700;
  text-anchor: middle;
}

.instrument-tag {
  fill: #526D80;
  font-size: 12px;
  font-weight: 700;
  text-anchor: middle;
}

.valve-tag {
  fill: #526D80;
  font-size: 12px;
  font-weight: 700;
  text-anchor: start;
  dominant-baseline: middle;
}

.thin-line {
  fill: none;
  stroke: var(--mechanical-color);
  stroke-width: 1.3;
  stroke-linecap: square;
  stroke-linejoin: miter;
}

.axis-line {
  fill: none;
  stroke: #71808A;
  stroke-width: 1.2;
  stroke-dasharray: 14 7 3 7;
}

.machine-body {
  fill: var(--mechanical-fill);
  stroke: var(--mechanical-color);
  stroke-width: 1.5;
}

.machine-light {
  fill: #EEF1F3;
  stroke: var(--mechanical-color);
  stroke-width: 1.3;
}

.machine-outline {
  fill: none;
  stroke: var(--mechanical-color);
  stroke-width: 1.5;
}

.sensor-body {
  fill: #FFFFFF;
  stroke: var(--mechanical-color);
  stroke-width: 1.2;
}

.sensor-detail {
  fill: none;
  stroke: var(--mechanical-color);
  stroke-width: 3;
}

.solid-detail {
  fill: var(--mechanical-color);
  stroke: none;
}

.motor-circle {
  fill: #FFFFFF;
  stroke: var(--mechanical-color);
  stroke-width: 1.4;
}

.motor-letter {
  fill: var(--mechanical-color);
  font-size: 13px;
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

.manual-value-slot {
  fill: #F7FBFD;
  stroke: var(--border-color);
  stroke-width: 1.1;
}

.blade {
  fill: #0A638F;
  stroke: #164E68;
  stroke-width: 1.2;
  stroke-linejoin: miter;
  visibility: hidden;
}

.blade.is-visible {
  visibility: visible;
}

.screen-footer {
  position: absolute;
  top: 685px;
  left: 30px;
  right: 30px;
  height: 56px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid var(--separator-color);
}

.footer-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.visual-button {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 142px;
  height: 40px;
  padding: 0 18px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: linear-gradient(180deg, #FFFFFF, #EEF5F8);
  color: #1C5A6B;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.brand-label {
  display: flex;
  align-items: center;
  height: 40px;
  color: #009999;
  font-size: 23px;
  font-weight: 700;
  letter-spacing: 1px;
}

