"use strict";

(function () {
  const SVG_NS = "http://www.w3.org/2000/svg";

  const BASE_WIDTH = 1610;
  const BASE_HEIGHT = 755;

  const DEFAULT_TITLE = "LÍNEA 3 / PLEGADOR 01";
  const DEFAULT_SUBTITLE =
    "Vista frontal de las depositadoras 1A y 1B";
  const DEFAULT_LEFT_NAME = "Depositadora 1A";
  const DEFAULT_RIGHT_NAME = "Depositadora 1B";
  const DEFAULT_REFERENCE = "041-xxx";

  const LEFT_SENSORS = [
    { tag: "-B621", x: 25, y: 232 },
    { tag: "-B623", x: 105, y: 232 },
    { tag: "-B631", x: 58, y: 289 },
    { tag: "-B633", x: 138, y: 289 },
    { tag: "-B622", x: 25, y: 343 },
    { tag: "-B624", x: 105, y: 343 },
    { tag: "-B632", x: 58, y: 401 },
    { tag: "-B634", x: 138, y: 401 }
  ];

  const RIGHT_SENSORS = [
    { tag: "-B641", x: 852, y: 232 },
    { tag: "-B643", x: 937, y: 232 },
    { tag: "-B651", x: 885, y: 289 },
    { tag: "-B653", x: 970, y: 289 },
    { tag: "-B642", x: 852, y: 343 },
    { tag: "-B644", x: 937, y: 343 },
    { tag: "-B652", x: 885, y: 399 },
    { tag: "-B654", x: 970, y: 399 }
  ];

  const CENTRAL_SENSORS = [
    { tag: "-B601", x: 216, y: 260, labelY: 309 },
    { tag: "-B602", x: 282, y: 260, labelY: 309 },
    { tag: "-B603", x: 444, y: 260, labelY: 309 },
    { tag: "-B604", x: 498, y: 260, labelY: 309 },
    { tag: "-B605", x: 640, y: 262, labelY: 234 },
    { tag: "-B606", x: 734, y: 262, labelY: 311 }
  ];

  const state = {
    name: "",
    left: false,
    right: false
  };

  let root = null;
  let stage = null;
  let leftBlade = null;
  let rightBlade = null;
  let leftTitle = null;
  let rightTitle = null;
  let referenceElement = null;
  let initialized = false;
  let receivedUpdate = false;
  let renderedName = null;

  function svgElement(tag, attributes, parent, text) {
    const element = document.createElementNS(SVG_NS, tag);

    Object.keys(attributes || {}).forEach(function (key) {
      element.setAttribute(key, String(attributes[key]));
    });

    if (text !== undefined) {
      element.textContent = text;
    }

    parent.appendChild(element);
    return element;
  }

  function addText(parent, text, x, y, className) {
    return svgElement(
      "text",
      {
        class: className || "instrument-tag",
        x: x,
        y: y
      },
      parent,
      text
    );
  }

  function addSensor(parent, configuration) {
    svgElement(
      "use",
      {
        href: "#p01-sensor",
        x: configuration.x,
        y: configuration.y,
        width: 32,
        height: 32
      },
      parent
    );

    addText(
      parent,
      configuration.tag,
      configuration.x + 16,
      configuration.labelY !== undefined
        ? configuration.labelY
        : configuration.y - 8
    );
  }

  function addUpperValve(parent, tag, x) {
    addText(parent, tag, x + 18, 61);

    svgElement(
      "rect",
      {
        class: "machine-light",
        x: x,
        y: 79,
        width: 24,
        height: 13
      },
      parent
    );

    svgElement(
      "path",
      {
        class: "thin-line",
        d: "M" + (x + 24) + " 85.5H" + (x + 36)
      },
      parent
    );

    svgElement(
      "path",
      {
        class: "machine-light",
        d:
          "M" + (x + 32) + " 71" +
          "H" + (x + 40) +
          "L" + (x + 36) + " 85.5Z " +
          "M" + (x + 32) + " 101" +
          "H" + (x + 40) +
          "L" + (x + 36) + " 85.5Z"
      },
      parent
    );
  }

  function addCylinder(parent, tag, x, top, labelY) {
    addText(parent, tag, x + 8, labelY);

    svgElement(
      "rect",
      {
        class: "machine-light",
        x: x,
        y: top,
        width: 16,
        height: 54
      },
      parent
    );

    svgElement(
      "path",
      {
        class: "thin-line",
        d:
          "M" + x + " " + (top + 5) +
          "H" + (x + 16) +
          "M" + x + " " + (top + 13) +
          "H" + (x + 16)
      },
      parent
    );

    svgElement(
      "rect",
      {
        class: "machine-light",
        x: x + 5,
        y: top + 13,
        width: 6,
        height: 57
      },
      parent
    );
  }

  function addValveAssembly(
    parent,
    centerX,
    top,
    upperTag,
    lowerTag
  ) {
    const lowerTop = top + 61;
    const valveY = top + 44;

    svgElement(
      "path",
      {
        class: "thin-line",
        d:
          "M" + centerX + " " + (top + 30) +
          "V" + lowerTop
      },
      parent
    );

    svgElement(
      "path",
      {
        class: "machine-light",
        d:
          "M" + (centerX - 15) + " " + (valveY - 4) +
          "L" + centerX + " " + valveY +
          "L" + (centerX - 15) + " " + (valveY + 4) +
          "Z " +
          "M" + (centerX + 15) + " " + (valveY - 4) +
          "L" + centerX + " " + valveY +
          "L" + (centerX + 15) + " " + (valveY + 4) +
          "Z"
      },
      parent
    );

    [top, lowerTop].forEach(function (y) {
      svgElement(
        "rect",
        {
          class: "machine-light",
          x: centerX - 6,
          y: y,
          width: 12,
          height: 30
        },
        parent
      );

      svgElement(
        "path",
        {
          class: "thin-line",
          d:
            "M" + centerX + " " + (y + 7) +
            "V" + (y + 12) +
            "H" + (centerX + 3) +
            "V" + (y + 18) +
            "H" + centerX +
            "V" + (y + 23)
        },
        parent
      );
    });

    addText(
      parent,
      upperTag,
      centerX + 13,
      top + 15,
      "valve-tag"
    );

    addText(
      parent,
      lowerTag,
      centerX + 13,
      lowerTop + 15,
      "valve-tag"
    );
  }

  function buildInstruments() {
    const left =
      document.getElementById("p01-left-instruments");
    const right =
      document.getElementById("p01-right-instruments");
    const central =
      document.getElementById("p01-central-sensors");

    left.replaceChildren();
    right.replaceChildren();
    central.replaceChildren();

    addUpperValve(left, "-Y636", 37);
    addUpperValve(left, "-Y638", 117);

    addUpperValve(right, "-Y656", 864);
    addUpperValve(right, "-Y658", 949);

    addCylinder(left, "MS-AS", 45, 131, 121);
    addCylinder(left, "MS-IS", 125, 131, 121);

    addCylinder(right, "PS-AS", 872, 132, 125);
    addCylinder(right, "PS-IS", 957, 132, 125);

    LEFT_SENSORS.forEach(function (sensor) {
      addSensor(left, sensor);
    });

    RIGHT_SENSORS.forEach(function (sensor) {
      addSensor(right, sensor);
    });

    CENTRAL_SENSORS.forEach(function (sensor) {
      addSensor(central, sensor);
    });

    addValveAssembly(left, 32, 463, "-Y626", "-Y627");
    addValveAssembly(left, 112, 463, "-Y628", "-Y629");

    addValveAssembly(right, 859, 462, "-Y646", "-Y647");
    addValveAssembly(right, 944, 461, "-Y648", "-Y649");
  }

  function own(object, key) {
    return !!object &&
      Object.prototype.hasOwnProperty.call(object, key);
  }

  function decodeBool(raw) {
    for (
      let depth = 0;
      depth < 4 && raw !== null && typeof raw === "object";
      depth += 1
    ) {
      if (own(raw, "value")) {
        raw = raw.value;
      } else if (own(raw, "on")) {
        raw = raw.on;
      } else {
        return false;
      }
    }

    if (raw === true || raw === 1) return true;
    if (raw === false || raw === 0) return false;

    if (typeof raw === "string") {
      const text = raw.trim().toLowerCase();
      return text === "true" || text === "1";
    }

    return false;
  }

  /*
   * Variable principal (w.value): aspa izquierda.
   * var1 (w.vars.var1): aspa derecha.
   * Una actualización parcial conserva el otro estado.
   */
  function applyUpdate(widget) {
    if (!widget || typeof widget !== "object") return;

    if (own(widget, "name")) {
      state.name =
        typeof widget.name === "string"
          ? widget.name
          : "";
    }

    if (own(widget, "value")) {
      state.left = decodeBool(widget.value);
    }

    const variables = widget.vars;

    if (
      variables &&
      typeof variables === "object" &&
      !Array.isArray(variables) &&
      own(variables, "var1")
    ) {
      state.right = decodeBool(variables.var1);
    }
  }

  function updateBlades() {
    leftBlade.classList.toggle("is-visible", state.left);
    rightBlade.classList.toggle("is-visible", state.right);

    leftBlade.setAttribute(
      "aria-hidden",
      String(!state.left)
    );
    rightBlade.setAttribute(
      "aria-hidden",
      String(!state.right)
    );
  }

  function fitHeader() {
    if (!stage) return;

    [
      [".screen-title", 28],
      [".screen-subtitle", 14]
    ].forEach(function (entry) {
      const element = stage.querySelector(entry[0]);

      if (!element || element.hidden) return;

      element.style.fontSize = entry[1] + "px";

      if (
        element.clientWidth > 0 &&
        element.scrollWidth > element.clientWidth
      ) {
        element.style.fontSize =
          (
            entry[1] *
            element.clientWidth /
            element.scrollWidth
          ) + "px";
      }
    });
  }

  function fitDepositorTitles() {
    [leftTitle, rightTitle].forEach(function (element) {
      if (!element) return;

      element.style.fontSize = "20px";

      const width = element.getComputedTextLength();
      const maxWidth = 200;

      if (width > maxWidth) {
        element.style.fontSize =
          (20 * maxWidth / width) + "px";
      }
    });
  }

  function updateTexts() {
    if (!stage) return;

    const name = state.name.trim();
    if (name === renderedName) return;
    renderedName = name;

    const parts = name.split("//");
    const hasSeparator = name.includes("//");

    const titleText =
      (parts[0] || "").trim() || DEFAULT_TITLE;

    const subtitleText =
      hasSeparator
        ? (parts[1] || "").trim()
        : DEFAULT_SUBTITLE;

    const leftText =
      parts.length > 2
        ? (parts[2] || "").trim() || DEFAULT_LEFT_NAME
        : DEFAULT_LEFT_NAME;

    const rightText =
      parts.length > 3
        ? (parts[3] || "").trim() || DEFAULT_RIGHT_NAME
        : DEFAULT_RIGHT_NAME;

    const referenceText =
      parts.length > 4
        ? (parts[4] || "").trim() || DEFAULT_REFERENCE
        : DEFAULT_REFERENCE;

    const title = stage.querySelector(".screen-title");
    const subtitle = stage.querySelector(".screen-subtitle");

    title.textContent = titleText;
    subtitle.textContent = subtitleText;
    subtitle.hidden = subtitleText === "";

    leftTitle.textContent = leftText;
    rightTitle.textContent = rightText;
    referenceElement.textContent = referenceText;

    fitHeader();
    fitDepositorTitles();
  }

  function fitStage() {
    if (!root || !stage) return;

    const width = root.clientWidth;
    const height = root.clientHeight;
    if (width <= 0 || height <= 0) return;

    const scale = Math.min(
      width / BASE_WIDTH,
      height / BASE_HEIGHT
    );

    stage.style.left =
      (width - BASE_WIDTH * scale) / 2 + "px";
    stage.style.top =
      (height - BASE_HEIGHT * scale) / 2 + "px";
    stage.style.transform = "scale(" + scale + ")";
  }

  function render() {
    if (!initialized) return;

    updateTexts();
    updateBlades();
  }

  window.onWidgetUpdate = function (widget) {
    receivedUpdate = true;
    applyUpdate(widget);
    render();
  };

  function initialize() {
    if (initialized) return;

    root = document.querySelector(".folder-widget");
    stage = document.querySelector(".folder-stage");

    leftBlade = document.getElementById("p01-left-blade");
    rightBlade = document.getElementById("p01-right-blade");
    leftTitle = document.getElementById("p01-title-left");
    rightTitle = document.getElementById("p01-title-right");
    referenceElement =
      document.getElementById("p01-screen-reference");

    if (
      !root || !stage ||
      !leftBlade || !rightBlade ||
      !leftTitle || !rightTitle ||
      !referenceElement
    ) {
      return;
    }

    buildInstruments();

    if (!receivedUpdate) {
      applyUpdate(window.WIDGET || null);
    }

    initialized = true;
    render();
    fitStage();

    if (typeof ResizeObserver !== "undefined") {
      const observer = new ResizeObserver(fitStage);
      observer.observe(root);
    } else {
      window.addEventListener("resize", fitStage);
    }

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(function () {
        fitHeader();
        fitDepositorTitles();
        fitStage();
      });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
